import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十九卦 涣 风水涣 巽上坎下","description":"周易 - 第五十九卦 涣 风水涣 巽上坎下","frontmatter":{"title":"第五十九卦 涣 风水涣 巽上坎下","description":"周易 - 第五十九卦 涣 风水涣 巽上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/060.md","filePath":"zh/classics/zhouyi/060.md"}'),l={name:"zh/classics/zhouyi/060.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="涣" tabindex="-1">涣 <a class="header-anchor" href="#涣" aria-label="Permalink to “涣”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。王假有庙，利涉大川，利贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>涣，亨。刚来而不穷，柔得位乎外而上同。王假有庙，王乃在中也。利涉大川，乘木有功也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>风行水上，涣；先王以享于帝立庙。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>用拯马壮，吉。象曰：初六之吉，顺 也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>涣奔其机，悔亡。象曰：涣奔其机，得愿也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>涣其躬，无悔。象曰：涣其躬，志在外也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>涣其群，元吉。涣有丘，匪夷所思。象曰：涣其群，元吉；光大也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>涣汗其大号，涣王居，无咎。象曰：王居无咎，正位也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>涣其血，去逖出，无咎。象曰：涣其血，远害也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
